INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(105449, 'ruRU', '', 'Если позволишь вставить слово, я хотел бы поговорить с тобой, $p.', 24330),
(105450, 'ruRU', '', 'По другую сторону лежит Арена Славы, где воины состязаются за превосходство в эпических битвах. Перед нами — Великий Медовый Зал, где рекой льются напитки и байки!', 24330),
(105451, 'ruRU', '', 'Крепость Хридсхал лежит к югу. Встретимся там. Слифна летает быстрее ветра.', 24330),
(105454, 'ruRU', '', 'Готов защищать меня, пока я провожу гадание?', 24330),
(105457, 'ruRU', '', 'Ночнорождённые обманули нас. Лунная Стража будет вскоре потеряна навеки.', 24330),
(105461, 'ruRU', '', 'Грязные псы... Тайдскорны всегда были безжалостными ворами и убийцами.', 24330),
(105462, 'ruRU', '', 'Моя наставница, Мелба, научила меня всему, что знала, включая боевые техники древних королей и королев-пивоваров врайкулов.', 24330),
(105463, 'ruRU', '', 'Надеюсь, Мелба сейчас смотрит на меня. Как долго я ждала этой мести!', 24330),
(105464, 'ruRU', '', 'Мы обрушимся на Пылающий Легион по твоей воле.', 24330),
(105468, 'ruRU', '', 'Осторожно! Это самозванец!', 24330),
(105469, 'ruRU', '', 'Яндвик никогда не падёт перед твоими мерзкими нагами! Никогда!', 24330),
(105473, 'ruRU', '', 'После моей смерти Один даровал мне проход в свои легендарные Чертоги Доблести. Именно здесь его воины пируют и празднуют вечную славу. Я скромно снабжаю его защитников их любимыми напитками.', 24330),
(105476, 'ruRU', '', 'Можешь гордиться, $n. Ты почти спас Яндвик. Теперь ты умрёшь в этой дыре, и ни Брандольф, ни Яндвик никогда не узнают, как ты не смог остановить Сашь''тар!', 24330),
(105522, 'ruRU', '', '|TInterface\\Icons\\Spell_Frost_SummonWaterElemental_2.blp:20|t %s начинает накладывать |cFFFF0000|Hspell:202098|h[Шквал солоноватых вод]|h|r. Берегись!', 24330),
(105526, 'ruRU', '', 'Я чувствую конфликт в сердце Чэня. Он хочет семью, и он хочет сражаться за мир. Он считает, что должен выбрать что-то одно, но это неправда.', 24330),
(105528, 'ruRU', '', 'Ему нужно решить, хочет ли он любить. Любить кого-то — значит принять ВСЁ целиком. И радость, И сердечную боль.', 24330),
(105530, 'ruRU', '', 'Я не поддалась.', 24330),
(105531, 'ruRU', '', 'Они делали... вещи... со мной.', 24330),
(105532, 'ruRU', '', 'Демоны обещали нам невообразимую силу.', 24330),
(105533, 'ruRU', '', 'Страж пытался убедить нас предать. Я слышала крики.', 24330),
(105534, 'ruRU', '', 'Сиана Ночная Глефа предала нас. Она примкнула к Легиону.', 24330),
(105535, 'ruRU', '', 'Ночная Глефа отправилась на юго-запад со стражем по имени Кордана Осквернённая Песнь.', 24330),
(105542, 'ruRU', '', 'Я не поддалась.', 24330),
(105543, 'ruRU', '', 'Они делали... вещи... со мной.', 24330),
(105544, 'ruRU', '', 'Демоны обещали нам невообразимую силу.', 24330),
(105545, 'ruRU', '', 'Страж пытался убедить нас предать. Я слышала крики.', 24330),
(105546, 'ruRU', '', 'Сиана Ночная Глефа предала нас. Она примкнула к Легиону.', 24330),
(105547, 'ruRU', '', 'Ночная Глефа отправилась на юго-запад со стражем по имени Кордана Осквернённая Песнь.', 24330),
(105548, 'ruRU', '', '<Авиана оглядывает горизонт неестественно острым взглядом.>\n\nПернатых тварей, которых вы зовёте соколозаврами, действительно нужно держать под контролем — такова природа равновесия.\n\nНо не меньше нужно держать под контролем и мою месть.\n\nСмертные не должны думать, что могут просто безнаказанно истреблять моих детей. Вы должны показать им, что мои крылья простираются над этими землями без конца.\n\nТы станешь моими когтями.\n\nЕсли примешь эту ношу — возьми этот сброшенный коготь и неси возмездие от моего имени.', 24330),
(105549, 'ruRU', '', '<Глаза Авианы сужаются, когда она видит твоё приближение.>\n\nЯ знаю, что ты наделал. Я вижу след из сломанных перьев и разбитых клювов, тянущийся за тобой.\n\n<Перья Авианы заметно взъерошиваются.>\n\nЧто ты можешь сказать в своё оправдание?', 24330),
(105550, 'ruRU', '', 'В моих владениях птенцов выбрасывают из гнезда, как только они смогут расправить крылья. Они летят. Или погибают.\n\nЯ создала испытание на ловкость для друидов, которых взяла под своё крыло. Хочешь тоже попробовать?\n\nС моим благословением ты сможешь грациозно парить в небесах... некоторое время.', 24330),
(105551, 'ruRU', '', 'REUSE', 24330),
(105554, 'ruRU', '', '<Авиана расправляет крылья на всю их ужасающую длину и смотрит на тебя, будто ты мышь.>\n\nТы удостаиваешь меня рассказами о законах природы? Я говорю от имени ветров и дикой природы, дитя. Не смей читать МНЕ лекции.\n\n<Она на мгновение замолкает, приглаживая перья.>\n\nИ всё же я вижу мудрость в твоих поступках, и я вижу в тебе доброту.\n\n<Она переводит взгляд с тебя на твоего соколозавра-скакуна и обратно.>\n\nТы сделал великое дело для этой матери и её птенца. Но преступления, совершённые против их рода, не могут остаться безнаказанными, ты понимаешь?', 24330),
(105562, 'ruRU', '', '<Авиана смотрит на тебя с хищным выражением.>\n\nЯ хочу почуять их кровь уже отсюда, Коготь.\n\nВидишь ворона позади себя, Побрякушку — обратись к нему, если понадобятся припасы для охоты. Он прекрасно умеет находить полезные и блестящие предметы.', 24330),
(105564, 'ruRU', '', 'Остальные иллидари не потревожат тебя здесь.', 24330),
(105566, 'ruRU', '', 'Я дарую тебе своё благословение, позволяющее грациозно спланировать на землю. Пока падаешь, постарайся собрать как можно больше изумрудных сфер.\n\nМало кто из птенцов собирает больше пары за первый полёт. Но большинство выживают, чтобы попробовать снова.\n\nЕсли соберёшь их все за один полёт, у меня может найтись для тебя кое-что особенное.', 24330),
(105569, 'ruRU', '', 'Атаки Легиона становятся всё чаще. Чем скорее мы сварим это Штормовое варево, тем лучше.', 24330),
(105570, 'ruRU', '', 'Этот и не ожидал такого.', 24330),
(105571, 'ruRU', '', 'Эта катушка создаёт ток высокой мощности. Катушку низкой мощности ты найдёшь в дальнем конце объекта.', 24330),
(105574, 'ruRU', '', 'Поговори со мной снова, когда вернёшься в Даларан. Нам нужно многое обсудить.', 24330);
